type OrderStatus =
  | { kind: 'pending' }
  | { kind: 'paid'; at: string }
  | { kind: 'shipped'; tracking: string }

function label(status: OrderStatus): string {
  switch (status.kind) {
    case 'pending': return 'Awaiting payment'
    case 'paid': return 'Paid at ' + status.at
    case 'shipped': return 'Tracking ' + status.tracking
  }
}
